create or replace function public.guard_employee_portfolio_insert() returns trigger language plpgsql set search_path = '' as $function$ begin if (select private.is_admin()) then return new; end if; if auth.uid() is null then return new; end if; if new.owner_id <> auth.uid() then raise exception 'Not allowed to create this portfolio'; end if; new.review_status := 'pending'; new.is_published := false; return new; end; $function$;
